 const message=t=>{if(a)a.status=t;const n=root.querySelector('#ss-status');if(n)n.textContent=t;};
 function change(action,value){if(screen!=='draft'||!a)return false;const next=changeStepWork(source,a.work,action,value);if(!next)return false;a.work=next;adopt();return true;}
 function on(sel,fn,target='#ss-title'){root.querySelectorAll(sel).forEach(n=>n.addEventListener('click',()=>{if(!live(n)||n.disabled)return;folds();message('');stopSpeech();if(fn(n)!==false)redraw(typeof target==='function'?target(n):target);}));}
 function select(sel,fn){root.querySelectorAll(sel).forEach(n=>n.addEventListener('change',()=>{if(!live(n)||n.disabled)return;folds();message('');stopSpeech();if(fn(n)!==false)redraw(sel);}));}
 on('[data-ss-back]',()=>{v.active=false;ctx.render?.();document.querySelector('#equality-heading')?.focus();return false;});on('[data-ss-working]',()=>{v.screen='draft';v.card=null;v.caseId=current(v)?.caseId||null;});on('[data-ss-shelf]',()=>{v.screen='shelf';v.card=null;});on('[data-ss-card]',n=>{v.card=n.dataset.ssCard;v.screen='card';const r=stepSheetsView(book).items.find(r=>r.readable&&r.id===v.card);v.caseId=r?known(r.raw.source):null;});on('[data-ss-earlier]',()=>{v.page--;},'[data-ss-later]');on('[data-ss-later]',()=>{v.page++;},'[data-ss-earlier]');
