 select('[data-ss-interval="0"]',n=>{const changed=change('select',{slot:0,index:Number(n.value)});if(changed&&a.work.idea!==null)a.status=T.ideaUnchanged;return changed;});select('[data-ss-interval="1"]',n=>{const changed=change('select',{slot:1,index:Number(n.value)});if(changed&&a.work.idea!==null)a.status=T.ideaUnchanged;return changed;});select('[data-ss-idea]',n=>change('idea',n.value||null));
 on('[data-ss-adjust]',n=>{const [i,axis,delta]=n.dataset.ssAdjust.split(':'),changed=change('adjust',{interval:a.work.selected[Number(i)],axis,delta:Number(delta)});if(changed&&Math.abs(a.work.steps[a.work.selected[Number(i)]][axis])===200)a.status=T.bound;return changed;},n=>{const [i,axis,delta]=n.dataset.ssAdjust.split(':'),value=a.work.steps[a.work.selected[Number(i)]][axis];return `[data-ss-adjust="${i}:${axis}:${Math.abs(value)===200?-Number(delta):delta}"]`;});on('[data-ss-compare]',()=>change('reference'),'#ss-reference-title');on('[data-ss-example]',()=>change('example'),'#ss-example-title');
 on('[data-ss-copy]',()=>{if(screen!=='card'||!a?.raw)return false;let k=v.copies.get(card);if(!k||!v.drafts.has(k)){const copy=add(v,a.raw.source,a.raw.work);copy.folds={...a.folds};k=v.key;v.copies.set(card,k);}v.key=k;v.screen='draft';v.card=null;v.caseId=current(v).caseId;});
